#!/usr/bin/env bash
#
# The system button: the right-most waybar module opens this. One list of the
# things that are not apps — power profile, theme, network, bluetooth, sound —
# each with its current value where it has one.
#
# Fonts come from rofi/.local/share/rofi/themes/minimal.rasi, colours from the
# theme-colors.rasi it imports (generated by theme.sh). -theme-str below
# carries layout only, and `inputbar { enabled: false; }` hides the search
# field the same way power_profile.sh does.

theme_sh=~/.config/hypr/scripts/theme.sh

# powerprofilesctl prints the id (power-saver); the menu shows the name.
case "$(powerprofilesctl get 2>/dev/null)" in
performance) profile="Performance" ;;
balanced) profile="Balanced" ;;
power-saver) profile="Power Saver" ;;
*) profile="" ;;
esac

current_id=$("$theme_sh" current)
current_name=$("$theme_sh" list | awk -F'\t' -v id="$current_id" '$1 == id { print $2 }')

# Labels are padded by hand, not with printf %-Ns: printf counts bytes in the C
# locale waybar may start us in, and ø and æ would push their value out of line.
options="󰓅  Strøm     $profile
󰏘  Tema      $current_name
󰖩  Netværk
󰂯  Bluetooth
󰕾  Lyd
󰒋  Send til hoth"

# -format i answers with the row number, so a label that happens to appear in a
# value (a theme called "Lyd") can never pick the wrong entry.
valgt=$(echo "$options" | rofi -dmenu -i -format i -p "System" \
  -theme-str "window { width: 300px; } \
                listview { lines: 6; } \
                inputbar { enabled: false; }")

case "$valgt" in
0) exec ~/.config/hypr/scripts/power_profile.sh ;;
1)
  # Current theme marked ●, the others ○, same as power_profile.sh's rows.
  ids=$("$theme_sh" list | cut -f1)
  rows=$("$theme_sh" list | while IFS=$'\t' read -r id name; do
    if [ "$id" = "$current_id" ]; then
      echo "●  $name"
    else
      echo "○  $name"
    fi
  done)
  count=$(echo "$rows" | wc -l)
  selected=$(echo "$ids" | grep -nx "$current_id" | cut -d: -f1)
  pick=$(echo "$rows" | rofi -dmenu -i -format i -p "Tema" \
    -selected-row "$(( ${selected:-1} - 1 ))" \
    -theme-str "window { width: 300px; } \
                  listview { lines: $count; } \
                  inputbar { enabled: false; }")
  [ -n "$pick" ] || exit 0
  exec "$theme_sh" set "$(echo "$ids" | sed -n "$(( pick + 1 ))p")"
  ;;
2) exec alacritty -e impala ;;
3) exec alacritty -e bluetui ;;
4)
  # wiremix is the TUI mixer; pavucontrol stays as the fallback for a machine
  # that has not got it installed yet.
  if command -v wiremix >/dev/null; then
    exec alacritty -e wiremix
  fi
  exec pavucontrol
  ;;
5) exec ~/.config/hypr/scripts/send-to-hoth.sh ;;
esac
